import { HStack, Skeleton, Text, VStack } from '@chakra-ui/react'
import { useDeepCompareEffect } from 'ahooks'
import { cloneElement, useState } from 'react'
import CetusMenu from '../CetusMenu'
import { feeConfigs } from './config'
import { PoolType, SelectFeeProps, SelectFeeType } from './type'

export const displayFeeKey: Record<PoolType, string> = {
  clmm: 'feeDisplay',
  dlmm: 'baseFeeDisplay'
}

function FeeSelect<T extends 'clmm' | 'dlmm'>({
  poolType = 'clmm',
  selectType = 'fee',
  value,
  options,
  children,
  onChange,
  wrapStyle = {},
  placement = 'bottom',
  loading = false
}: SelectFeeProps<T>) {
  const { color, activeBorderColor, hoverBorderColor, defaultOptions } = feeConfigs[poolType]
  const [list, setList] = useState<any[]>(selectType === 'fee' ? (defaultOptions as SelectFeeType<T>[]) : [])
  const [open, setOpen] = useState(false)

  useDeepCompareEffect(() => {
    if (options) {
      if (poolType === 'clmm') {
        const index = options.findIndex(ele => ele.feeDisplay === '0.001%' && !ele.poolAddress)
        if (index !== -1) {
          options.splice(index, 1)
        }
      }
      setList(options)
    }
  }, [options])

  return (
    <CetusMenu
      isLazy
      isOpen={open}
      onClose={() => setOpen(false)}
      placement={placement}
      defaultMaxH="315px"
      listProps={{
        p: '8px',
        borderRadius: '12px',
        w: { base: 'calc(100vw - 24px)', lg: '260px' },
        overflowY: 'auto',
        ...wrapStyle
      }}
    >
      {typeof children === 'function'
        ? children({
            isOpen: open,
            onClick: () => setOpen(!open)
          })
        : cloneElement(children, {
            isOpen: open,
            onClick: () => setOpen(!open)
          })}
      <VStack w="100%" gap="8px" p="0">
        {loading && selectType === 'binStep'
          ? list?.map(item => <Skeleton key={`${item?.binStep}`} h="40px" w="100%" />)
          : list?.map(item => (
              <HStack
                as="button"
                w="100%"
                p="0 12px"
                h="40px"
                key={selectType === 'fee' ? item?.feeDisplay : `${item?.binStep}-${item?.baseFactor}`}
                justify="space-between"
                disabled={item?.disabled}
                onClick={() => {
                  onChange?.(item)
                  setOpen(false)
                }}
                borderRadius="8px"
                border="1px solid"
                bg="bg_six"
                cursor={item?.disabled ? 'not-allowed' : 'pointer'}
                borderColor={
                  (selectType === 'fee' ? value?.fee === item?.fee : value?.binStep === item?.binStep && value?.baseFactor === item?.baseFactor)
                    ? 'primary'
                    : 'border'
                }
                sx={{
                  _hover: {
                    borderColor: 'primary_opacity.60'
                  }
                }}
              >
                <HStack gap="8px">
                  {selectType === 'fee' && (
                    <Text color="text_caption" fontWeight="500">
                      {item?.feeDisplay}
                    </Text>
                  )}

                  {selectType === 'binStep' && (
                    <Text color="text_caption" fontWeight="500">
                      {item?.binStep} bps
                    </Text>
                  )}
                </HStack>

                <VStack align="flex-end" gap="4px">
                  <Text fontSize="12px" color="text_caption">
                    {item?.title}
                  </Text>
                </VStack>
              </HStack>
            ))}
      </VStack>
    </CetusMenu>
  )
}

export default FeeSelect
